CREATE COLUMN TABLE "TEST_AP"."OPRO" ("AbsEntry" INTEGER CS_INT NOT NULL , "MapID" INTEGER CS_INT NOT NULL , "Code" INTEGER CS_INT NOT NULL , "Type" NVARCHAR(6) DEFAULT 'Strin', "Name" NVARCHAR(50) NOT NULL , "IsBlob" NVARCHAR(1), "TValue" NVARCHAR(250), "BValue" BLOB MEMORY THRESHOLD 1000, "Encoding" NVARCHAR(20), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OPRO_CODE_NAME" ON "TEST_AP"."OPRO" ( "MapID" ASC, "Code" ASC, "Name" ASC )